<template><Layout><div class="breadcrumb"><Link :href="route('dashboard')">Overview</Link><span>›</span>Products</div><div class="page-header"><div><div class="eyebrow">MARKETPLACE CATALOGUE</div><h1>Selling products</h1><p>Review every product listed by your community.</p></div></div><section class="product-summary"><div><strong>{{ products.length }}</strong><span>Total listings</span></div><div><strong>{{ active }}</strong><span>Active listings</span></div><div><strong>{{ sold }}</strong><span>Sold out</span></div><div><strong>{{ stock }}</strong><span>Units available</span></div></section><section class="product-controls"><div class="list-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input v-model="query" placeholder="Search product, seller or category…"/></div><select v-model="filter"><option value="all">All products</option><option value="active">Active</option><option value="inactive">Inactive</option><option value="selling">Selling</option><option value="sold-out">Sold out</option><option value="on-hold">On hold</option></select><span>{{ filtered.length }} products</span></section><section v-if="filtered.length" class="product-grid"><Link v-for="product in filtered" :key="product.id" :href="route('selling-products.show',product.id)" class="product-card"><div class="product-cover"><img v-if="product.cover" :src="product.cover"/><span v-else>SW</span><b :class="statusClass(product)">{{ product.is_active?readable(product.status):'Inactive' }}</b></div><div class="product-body"><div class="product-category">{{ product.category?.name||'Uncategorised' }}</div><h2>{{ product.name }}</h2><div class="seller-line"><span class="tiny-avatar"><img v-if="product.seller?.image" :src="product.seller.image"/><b v-else>{{ initial(product.seller?.name) }}</b></span>{{ product.seller?.name||'Deleted seller' }}</div><div class="product-meta"><strong>{{ money(product.price) }}</strong><span>{{ product.quantity }} in stock</span></div></div></Link></section><section v-else class="listing-panel empty-state"><div>⌕</div><strong>No products found</strong><p>Try changing your search or filter.</p></section></Layout></template>
<script setup>import{ref,computed,onMounted}from'vue';import{usePage}from'@inertiajs/vue3';import{useToast}from'vue-toastification';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';const props=defineProps({products:{type:Array,default:()=>[]}}),query=ref(''),filter=ref('all');const active=computed(()=>props.products.filter(p=>p.is_active).length),sold=computed(()=>props.products.filter(p=>p.status==='sold-out').length),stock=computed(()=>props.products.reduce((n,p)=>n+p.quantity,0));const filtered=computed(()=>{const q=query.value.toLowerCase();return props.products.filter(p=>[p.name,p.seller?.name,p.category?.name].some(v=>v?.toLowerCase().includes(q))&&(filter.value==='all'||filter.value==='active'&&p.is_active||filter.value==='inactive'&&!p.is_active||p.status===filter.value))});const money=v=>new Intl.NumberFormat('en-US').format(v)+' Ks',readable=s=>s.replaceAll('-',' ').replace(/\b\w/g,l=>l.toUpperCase()),initial=n=>(n||'?').charAt(0).toUpperCase(),statusClass=p=>!p.is_active?'product-inactive':p.status==='selling'?'product-active':p.status==='sold-out'?'product-sold':'product-hold';const page=usePage(),toast=useToast();onMounted(()=>{if(page.props.flash?.success)toast.success(page.props.flash.success)});</script>
